/* checker daemon: verify the peer identity, not a payload field */
struct ucred cr; socklen_t len = sizeof cr;
getsockopt(conn, SOL_SOCKET, SO_PEERCRED, &cr, &len);
if (cr.uid == req->initiated_by_uid)
    reply(conn, "self-approval denied");
else
    reply(conn, approve(req, cr.uid) ? "approved" : "denied");
